  6 | import { appendSystemLog } from '../store/logAtom.js';
  7 | import type { WorkingStatus } from '../store/ui-state.js';
  8 | import { MessageStream } from '@anthropic-ai/sdk/lib/MessageStream.mjs';
  9 | import { getClient } from './client.js';
 10 | import { clearBackups } from '../utils/fileHistory.js';
 11 | import mitt from 'mitt';
 12 | 
 13 | export type AgentTurnEvents = {
 14 |   'stream:create': MessageStream<null>;
 15 |   'tool:use': {
 16 |     toolUseId: string;
 17 |     toolName: string;
 18 |     toolInput: Record<string, any>;
