 4 | // ── Retry configuration ──
 5 | 
 6 | const RETRY_MAX_ATTEMPTS = 3;
 7 | const RETRY_BASE_DELAY_MS = 1_000;
 8 | const RETRY_MAX_DELAY_MS = 30_000;
 9 | 
10 | function isRetryable(error: unknown): boolean {
11 |   if (error instanceof Anthropic.RateLimitError) return true;
12 |   if (error instanceof Anthropic.APIConnectionError) return true;
13 |   if (error instanceof Anthropic.APIConnectionTimeoutError) return true;
14 |   if (error instanceof Anthropic.InternalServerError) return true;
15 |   if (error instanceof Anthropic.APIUserAbortError) return false;
16 |   // 其他（认证错误、非法请求等）不重试
17 |   return false;
18 | }
19 | 
20 | /**
21 |  * 错误重试插件：当 API 调用遇到可重试错误时自动重试。
22 |  */
23 | export class ErrorHandlerPlugin extends MicaPlugin {
24 |   onInstall(): void {
25 |     this.agent.agentTurn.use(async (userInput, next, onIteration) => {
26 |       let attempt = 0;
27 |       while (attempt < RETRY_MAX_ATTEMPTS) {
28 |         try {
29 |           return await next(userInput, onIteration);
30 |         } catch (error) {
31 |           attempt++;
32 |           if (!isRetryable(error) || attempt >= RETRY_MAX_ATTEMPTS) throw error;
33 |           const delay = Math.min(RETRY_BASE_DELAY_MS * 2 ** attempt, RETRY_MAX_DELAY_MS);
34 |           let restTime = delay / 1000;
35 |           const msgId = this.showMessage(`第 ${attempt} 次重试失败，${restTime}s 后重试...`);
36 |           const timer = setInterval(() => {
37 |             restTime -= 1;
38 |             this.showMessage(`第 ${attempt} 次重试失败，${restTime}s 后重试...`);
39 |           }, 1000);
40 |           await new Promise((resolve) =>
41 |             setTimeout(() => {
42 |               clearInterval(timer);
43 |               this.removeMessage(msgId);
44 |               resolve(true);
45 |             }, delay),
46 |           );
47 |         }
48 |       }
49 |     });
50 |   }
51 | }
